import java.util.*;
public class DoublyLinkedList { static class Node{int x;Node prev,next;Node(int x){this.x=x;}} Node head,tail; public void addLast(int x){Node n=new Node(x);if(tail==null)head=tail=n;else{tail.next=n;n.prev=tail;tail=n;}} public int removeLast(){if(tail==null)throw new NoSuchElementException("empty deque");int x=tail.x;tail=tail.prev;if(tail==null)head=null;else tail.next=null;return x;} public String toString(){StringBuilder s=new StringBuilder("[");for(Node n=head;n!=null;n=n.next){if(s.length()>1)s.append(", ");s.append(n.x);}return s.append("]").toString();} public static void run(){DoublyLinkedList l=new DoublyLinkedList();l.addLast(10);l.addLast(20);l.addLast(30);System.out.println("Doubly linked list: "+l+", removeLast="+l.removeLast()+", now "+l);System.out.println("Invariant: next and prev links agree; endpoint operations O(1).\n");} public static void main(String[] args){run();}}
